def parse_date(text):
    """(year, month, day) from text such as 2026-03-09."""
    year, month, day = text.split("-")
    return int(year), int(day), int(month)

files.test_dates.py:
from dates import parse_date


def test_parse():
    assert parse_date('2026-03-09') == (2026, 3, 9)


def test_december():
    assert parse_date('1999-12-31') == (1999, 12, 31)

files.users.py:
def find_user(users, name):
    """The user with this name, or None."""
    for user in users:
        if user["name"] == name:
            return user
    return None

files.test_users.py:
from users import find_user

USERS = [{'name': 'Alice', 'id': 1}, {'name': 'bob', 'id': 2}]


def test_exact():
    assert find_user(USERS, 'Alice')['id'] == 1


def test_other_case():
    assert find_user(USERS, 'alice')['id'] == 1
    assert find_user(USERS, 'BOB')['id'] == 2


def test_missing():
    assert find_user(USERS, 'carol') is None

